410→async function createDocumentPackageSigner(prisma, req, creator, companyId, userId, documentHeaderId, recipients, send_reminder, reminder_days_interval) {
411→    const fingerprint = await generateFingerPrint();
412→
413→    const expires_date = new Date(req.expires_in_days);
414→    formatted_expires_date = expires_date.toISOString();
415→    
416→    const current_date = new Date();
417→    const formatted_current_date = current_date.toISOString();
418→
419→    const request = await prisma.document_packages_signers.create({
420→        data: {
421→            document_package_header_id: parseInt(documentHeaderId),
422→            user_id: parseInt(userId),
423→            company_id: parseInt(companyId),
424→            status: "send",
425→            token: "",
426→            is_pdf: 1,
427→            sent_sign_request_at: formatted_current_date,
428→            fingerprint: fingerprint.replace(":", ""),
429→            ip_address: req.ip,
430→            from_api: 1,
431→            user_id_creator: parseInt(creator),
432→            active: "1",
433→            reminder_days_interval: reminder_days_interval ? reminder_days_interval : null,
434→            send_reminder: send_reminder == 1 ? true : false,
435→            expires_in_days: formatted_expires_date,
436→            created_at: new Date(),
437→            updated_at: new Date()
438→        }
439→    });
440→
441→    if (recipients.length > 0) {
442→        const validRecipients = recipients.filter(recipient => recipient.email && recipient.email.trim() !== '');
443→
444→        if (validRecipients.length > 0) {
445→            for (let i = 0; i < validRecipients.length; i++) {
446→                const recipient = validRecipients[i];
447→    
448→                await prisma.request_recipients.create({
449→                    data: {
450→                        document_package_signer_id: request.id,
451→                        type: 1,
452→                        email: recipient.email,
453→                        created_at: new Date(),
454→                        updated_at: new Date(),
455→                    },
456→                });
457→    
458→                await prisma.document_packages_signers_logs.create({
459→                    data: {
460→                        document_package_signer_id: request.id,
461→                        event_description: `Destinatario agregado: ${recipient.email}`,
462→                        ip_address: req.ip ? req.ip : null,
463→                        performed_by_user_id: parseInt(creator),
464→                        created_at: new Date(),
465→                    },
466→                });
467→            }
468→        } else {
469→            console.log("No hay destinatarios válidos");
470→        }
471→    }
472→
473→    return request;
474→}
