477→async function sendSignRequests(res, documentPackageSigner, users, company, signerFields, packageName, documentPackageHeader, prisma) {
478→    const requests = [];
479→    let requestSending = false;
480→
481→    try {
482→        for (const user of users) {
483→            const token = service.createCustomToken({
484→                id: user.id,
485→                document_package_signer_id: documentPackageSigner.id,
486→            });
487→
488→            const fingerprint = await generateFingerPrint();
489→
490→            const signerField = signerFields.find(field => field.correo.toLowerCase().trim() == user.email.toLowerCase().trim());
491→
492→            if (!signerField) {
493→                console.error(`No se encontró signerField para el usuario con correo: ${user.email}`);
494→                continue;  
495→            }
496→
497→            const orderMatch = signerField.signer_order;
498→            const order = orderMatch ? parseInt(orderMatch) : users.indexOf(user) + 1;
499→
500→            await prisma.document_signers.create({
501→                data: {
502→                    document_package_signer_id: documentPackageSigner.id,
503→                    user_id: parseInt(user.id),
504→                    order: order, 
505→                    status: "send",
506→                    token: token,
507→                    sent_sign_request_at: new Date(),
508→                    fingerprint: fingerprint.replace(":", ""),
509→                    expires_in_days: documentPackageSigner.expires_in_days,
510→                    created_at: new Date(),
511→                    updated_at: new Date()
512→                },
513→            });
514→
515→            const url = `${process.env.ENV_URL}${token}`;
516→
517→            if (documentPackageHeader.order == 1 && parseInt(order) === 1) {
518→                requests.push({
519→                    email: user.email,
520→                    company: company,
521→                    firstname: user.firstname,
522→                    lastname: user.lastname,
523→                    passwordGenerated: genApiKey.generateApiKey({ method: "base32", dashes: false }),
524→                    date: documentPackageSigner.expires_in_days.toLocaleDateString('es-ES'),
525→                    time: documentPackageSigner.expires_in_days.toLocaleTimeString(),
526→                    _url: url,
527→                    company_email: company.email,
528→                    sendRequest: true
529→                });
530→            }
531→
532→            if (documentPackageHeader.order === 2) {
533→                requests.push({
534→                    id: user.id,
535→                    document_package_signer_id: documentPackageSigner.id,
536→                    email: user.email,
537→                    company: company,
538→                    firstname: user.firstname,
539→                    lastname: user.lastname,
540→                    passwordGenerated: genApiKey.generateApiKey({ method: "base32", dashes: false }),
541→                    date: documentPackageSigner.expires_in_days.toLocaleDateString('es-ES'),
542→                    time: documentPackageSigner.expires_in_days.toLocaleTimeString(),
543→                    _url: url,
544→                    company_email: company.email,
545→                    sendRequest: true
546→                });
547→            }
548→        }
549→
550→        requestSending = true;
551→
552→    } catch (error) {
553→        console.error("Error al generar las solicitudes de firma:", error);
554→    }
555→
556→
557→    await Promise.all(requests.map(async (user) => {
558→        if (requestSending) {
559→
560→            if (user.sendRequest) {
561→                await service.sendSolicitudFirma(
562→                    user.email,
563→                    user.company.avatar,
564→                    `${user.firstname} ${user.lastname}`,
565→                    user.company.fiscal_name,
566→                    user.company.fiscal_name,
567→                    user.passwordGenerated,
568→                    user.date,
569→                    user.time,
570→                    user._url,
571→                    user.company_email,
572→                    packageName,
573→                    user.company.advanced_settings[0].email_message || "",
574→                    user.id,
575→                    user.document_package_signer_id,
576→                    user.company.id
577→                );
578→            }
579→        }
580→    }));
581→   
582→}
