import Axios from 'axios'
import urls from './urls'
import toast from '../sweet-alert'
import i18n from '../i18n'
import state from '../state'
import Swal from 'sweetalert2'

export const axios = Axios.create({
  baseURL: import.meta.env.VITE_API_BASE_URL,
});


axios.interceptors.response
    .use(
        response => {
            state.loading_data.update(false)
            responseAlert(response)
            return response;
        },
        error => {
            state.loading_data.update(false)
            responseAlert(error.response)
            throw error
        },
    )
;

// Request
export const request = options => {

    const token = localStorage.getItem('token')

    state.loading_data.update(true)

    return axios
        .request({
            ...options,
            headers: {
                ...token && { Authorization: `Bearer ${token}` },
                ...options.headers,
            },
            ...options.buildURL && buildURL(options.buildURL),
        })
        .then(res => res.data)
        .catch(err => {

           /*  return err; */
        });
}

// URL builder
const buildURL = ({key, params}) => {

    // 
    var url = urls

    var prefix = ''

    // Keys
    var keys = key.split('.')
    keys.forEach(item => {

        // URL existing
        url = { ...url?.[item] }
        if (!url) throw new Error('URL not found')

        // Prefix concat
        prefix += url.prefix ? `/${url.prefix}` : ''

        // Children
        url = url.children || url
    });

    // Prefix
    url.url = `${prefix}/${url.url}`

    // Params
    let URLSections = url.url.match(/(:[A-Za-z])\w+[?]?/g)
    if (URLSections) {
        URLSections.forEach(paramKey => {

            let paramKey2 = paramKey.replace(':', '').replace('?', '')

            let paramValue = params?.[paramKey2] !== undefined ? params?.[paramKey2] : ''

            url.url = url.url.replace(
                paramKey,
                paramValue,
            )
            .replace('//', '/')
        });
    }

    return url
}

// Response alert
const responseAlert = response => {

    // Status
    const status = response.status

    // Key
    const key = 
        // Info
        (status >= 100 && status < 200) ? 'info' :
        // Success
        (status >= 200 && status < 300) ? 'success' :
        // Error
        (status >= 400 && status < 600) ? 'error' :
        // Other
        null;

    // Exit if no alert is needed
    if (response.config.alert !== true && !response.config.alert?.[key]) return

    // Get message from server or default message
    let title = response.response?.data?.message || response.data?.message
    title = title || (key && i18n.tc(`app_${key}`));

    // Build alert configuration
    const alertOptions = {
        icon: key,
        title,
         didOpen: (modal) => {
            // El contenedor principal de la alerta es el padre del elemento modal.
            // Le asignamos un z-index alto para que aparezca sobre otros elementos.
            if (modal.parentElement) {
                modal.parentElement.style.zIndex = '9999';
            }
        },
        ...response.config.alert?.[key]
    };

    // Fire alert using Swal
    Swal.fire(alertOptions);
}

