input.new_string:
async saveData() {
    if (this.data.length === 0) {
        this.showToast("No hay registros para guardar. Debe importar al menos un registro.");
        return;
    }

    this.progressData = {
        processed: 0,
        total: this.data.length,
        failed: 0,
        status: 'processing',
    };
    this.progressDialog = true;
    this.modelItem.editing.dialogStatus = false;

    const token = localStorage.getItem('token');
    const baseURL = import.meta.env.VITE_API_BASE_URL;
    const url = `${baseURL}/admin/update_pdf_content_massive`;

    try {
        const response = await fetch(url, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                ...(token && { 'Authorization': `Bearer ${token}` }),
            },
            body: JSON.stringify({
                documentHeaderId: this.document.id,
                data: this.data,
                fields: this.allFieldsForSubmit,
                company_id: this.$state.auth_user.data.company_id,
                user_id_creator: this.$state.auth_user.data.id,
                name: this.name,
                recipients: this.recipients,
                sendReminder: this.sendReminder,
                reminder_days_interval: this.reminder_days_interval,
            }),
        });

        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let buffer = '';

        while (true) {
            const { done, value } = await reader.read();
            if (done) break;

            buffer += decoder.decode(value, { stream: true });

            const lines = buffer.split('\n');
            buffer = lines.pop();

            let eventName = '';
            for (const line of lines) {
                if (line.startsWith('event: ')) {
                    eventName = line.substring(7).trim();
                } else if (line.startsWith('data: ') && eventName) {
                    try {
                        const data = JSON.parse(line.substring(6));
                        this.handleSSEEvent(eventName, data);
                    } catch (e) {
                        // ignore parse errors on partial chunks
                    }
                    eventName = '';
                }
            }
        }
    } catch (error) {
        console.error('Error en saveData SSE:', error);
        this.progressData.status = 'error';
    }
},

handleSSEEvent(eventName, data) {
    if (eventName === 'progress') {
        this.progressData.processed = data.processed;
        this.progressData.total = data.total;
        this.progressData.failed = data.failed || 0;
    } else if (eventName === 'complete') {
        this.progressData.processed = data.count;
        this.progressData.total = data.total;
        this.progressData.failed = data.failed || 0;
        this.progressData.status = 'complete';
    } else if (eventName === 'error') {
        this.progressData.status = 'error';
    }
},

onProgressClose() {
    this.progressDialog = false;
    if (this.progressData.status === 'complete' && this.progressData.failed === 0) {
        Swal.fire({
            title: "¡Solicitudes realizadas exitosamente!",
            icon: 'success',
            text: `Se han generado ${this.progressData.processed} de ${this.progressData.total} documentos.`,
            confirmButtonText: this.$tc('confirm'),
        }).then(result => {
            if (result) {
                this.$router.push({ name: 'admin.list-signature-request.list' });
            }
        });
    } else if (this.progressData.status === 'complete' && this.progressData.failed > 0) {
        Swal.fire({
            title: "Proceso finalizado con errores",
            icon: 'warning',
            text: `Se generaron ${this.progressData.processed} documentos correctamente. ${this.progressData.failed} registro(s) fallaron.`,
